-- 仅本地隔离数据库验收；全部测试记录最终回滚。
begin;
create temporary table qa_forwarding_results(test text,result text);
grant all on qa_forwarding_results to authenticated;
insert into public.orders(order_no,merchant_id,warehouse_id,status,route_code,route_name,destination_address,recipient_name,recipient_phone,origin_warehouse_name,origin_warehouse_address,destination_overseas_warehouse_id,destination_warehouse_snapshot)
select 'QA-FORWARD-HEAD',p.id,w.id,'shipped','ID-SEA','QA海运',ow.address_line,ow.contact_name,ow.contact_phone,'QA深圳','QA深圳测试地址',ow.id,to_jsonb(ow)
from public.profiles p cross join public.warehouses w cross join public.overseas_warehouses ow where p.role='merchant' and w.code='SZ-LG-01' and ow.code='ID-JKT-TEST' limit 1;
insert into public.fees(order_id,fee_breakdown_version,shipping_fee,handling_fee,total_amount,confirmed_at) select id,3,60,18,78,now() from public.orders where order_no='QA-FORWARD-HEAD';
insert into public.payments(order_id,merchant_id,amount,status) select id,merchant_id,78,'paid' from public.orders where order_no='QA-FORWARD-HEAD';
grant usage on schema public to authenticated;
set local role authenticated;
do $$
declare m uuid;a uuid;w uuid;h public.orders;t1 public.orders;t2 public.orders;t3 public.orders;again public.orders;
 z public.last_mile_zones;pkg1 uuid;pkg2 uuid;pkg3 uuid;request uuid:=gen_random_uuid();err text;
 recipient jsonb:='{"country":"印度尼西亚","recipient_name":"QA消费者","recipient_phone":"TEST-PHONE","city":"Jakarta","address_line":"QA测试地址，禁止寄件"}';
 f public.fees;ac public.payment_receiving_accounts;r public.payment_receipts;obj text;
begin
 -- 预置本地固定人员，无外部账号写入。
 m:='10000000-0000-0000-0000-000000000001';a:='10000000-0000-0000-0000-000000000002';w:='10000000-0000-0000-0000-000000000003';
 perform set_config('request.jwt.claim.sub',m::text,true);select * into h from public.orders where order_no='QA-FORWARD-HEAD';
 select * into z from public.last_mile_zones where warehouse_id=h.destination_overseas_warehouse_id and is_active order by reference_distance_km limit 1;
 err:=null;begin perform public.warehouse_receive_overseas_packages(h.id,array['QA-BOX-1'],'商家越权',false);exception when others then err:=sqlerrm;end;if err is null then raise exception '商家可入库';end if;
 perform set_config('request.jwt.claim.sub',w::text,true);
 err:=null;begin perform public.warehouse_receive_overseas_packages(h.id,array['QA-BOX-1'],'未分配权限',false);exception when others then err:=sqlerrm;end;if err is null then raise exception '未分配海外仓可入库';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.admin_set_overseas_staff((select member_no from public.profiles where id=w),h.destination_overseas_warehouse_id,true);
 perform set_config('request.jwt.claim.sub',w::text,true);
 h:=public.warehouse_receive_overseas_packages(h.id,array['QA-BOX-1'],'第一批',false);
 perform public.warehouse_receive_overseas_packages(h.id,array['QA-BOX-1'],'重复扫码',false);
 if (select count(*) from public.overseas_packages where source_order_id=h.id)<>1 or h.overseas_receiving_completed_at is not null then raise exception '重复入库或部分到货错误';end if;
 err:=null;begin insert into public.overseas_packages(package_no,source_order_id,merchant_id,overseas_warehouse_id,received_by) values('DIRECT-BYPASS',h.id,m,z.warehouse_id,w);exception when others then err:=sqlerrm;end;if err is null then raise exception '直接写入库存未被拒绝';end if;
 insert into qa_forwarding_results values('商家及未分配仓库人员越权拒绝、真实外箱分批入库、重复扫码不重复、禁止直接写库存','PASS');
 perform set_config('request.jwt.claim.sub',m::text,true);
 select id into pkg1 from public.overseas_packages where package_no='QA-BOX-1';
 err:=null;begin perform public.merchant_create_forwarding(h.id,array[pkg1,pkg1],recipient,z.id,z.updated_at,request);exception when others then err:=sqlerrm;end;if err is null then raise exception '重复箱号可建单';end if;
 err:=null;begin perform public.merchant_create_forwarding(h.id,array[pkg1],recipient-'address_line',z.id,z.updated_at,request);exception when others then err:=sqlerrm;end;if err is null then raise exception '空地址可建单';end if;
 err:=null;begin perform public.merchant_create_forwarding(h.id,array[pkg1],recipient,z.id,z.updated_at-interval '1 second',request);exception when others then err:=sqlerrm;end;if err is null then raise exception '过期地区版本可建单';end if;
 t1:=public.merchant_create_forwarding(h.id,array[pkg1],recipient,z.id,z.updated_at,request);
 again:=public.merchant_create_forwarding(h.id,array[pkg1],recipient,z.id,z.updated_at,request);
 if t1.id<>again.id or (select status from public.overseas_packages where id=pkg1)<>'reserved' then raise exception '幂等或占用失败';end if;
 err:=null;begin perform public.merchant_create_forwarding(h.id,array[pkg1],recipient||'{"city":"Bali"}',z.id,z.updated_at,request);exception when others then err:=sqlerrm;end;if err is null then raise exception '同请求可替换地址';end if;
 err:=null;begin perform public.merchant_create_forwarding(h.id,array[pkg1],recipient,z.id,z.updated_at,gen_random_uuid());exception when others then err:=sqlerrm;end;if err is null then raise exception '已占用可重复建单';end if;
 insert into qa_forwarding_results values('重复选择、缺失地址、过期运价拒绝；请求重试不重复；已占用不能二次派单','PASS');
 perform set_config('request.jwt.claim.sub',w::text,true);
 err:=null;begin perform public.warehouse_dispatch_forwarding(t1.id,'J&T','QA-JT-1');exception when others then err:=sqlerrm;end;if err is null then raise exception '未付款可出库';end if;
 f:=public.warehouse_quote_last_mile_distance(t1.id,z.id,50,'QA距离核对',z.updated_at);
 perform set_config('request.jwt.claim.sub',m::text,true);
 t1:=public.merchant_cancel_forwarding(t1.id);
 if t1.status<>'cancelled' or (select status from public.overseas_packages where id=pkg1)<>'available' then raise exception '取消未释放';end if;
 t2:=public.merchant_create_forwarding(h.id,array[pkg1],recipient,z.id,z.updated_at,gen_random_uuid());
 perform set_config('request.jwt.claim.sub',w::text,true);
 h:=public.warehouse_receive_overseas_packages(h.id,array['QA-BOX-2','QA-BOX-3'],'第二批到齐',true);
 err:=null;begin perform public.warehouse_receive_overseas_packages(h.id,array['QA-BOX-4'],'到齐后追加',false);exception when others then err:=sqlerrm;end;if err is null then raise exception '到齐后可追加';end if;
 if h.overseas_receiving_completed_at is null then raise exception '到齐标记未保存';end if;
 perform set_config('request.jwt.claim.sub',m::text,true);
 select id into pkg2 from public.overseas_packages where package_no='QA-BOX-2';select id into pkg3 from public.overseas_packages where package_no='QA-BOX-3';
 t3:=public.merchant_create_forwarding(h.id,array[pkg2],recipient||'{"recipient_name":"QA第二消费者"}',z.id,z.updated_at,gen_random_uuid());
 if t2.id=t3.id or t3.parent_order_id<>t2.parent_order_id or (select count(*) from public.orders where parent_order_id=h.id)<>3 then raise exception '一头程多尾程失败';end if;
 insert into qa_forwarding_results values('未付款禁止出库、取消释放可重申请、二次到货、全部到齐后禁止新增、一头程多消费者尾程','PASS');
 perform set_config('request.jwt.claim.sub',w::text,true);
 f:=public.warehouse_quote_last_mile_distance(t2.id,z.id,50,'QA距离核对',z.updated_at);
 perform set_config('request.jwt.claim.sub',m::text,true);
 select * into ac from public.payment_receiving_accounts where singleton;
 obj:=m||'/'||t2.id||'/qa.png';
 insert into storage.objects(bucket_id,name,metadata) values('payment-proofs',obj,'{"size":128,"mimetype":"image/png"}');
 r:=public.merchant_submit_payment_receipt(t2.id,obj,'QA付款人','QA转账',now(),'仅隔离测试',ac.updated_at);
 err:=null;begin perform public.merchant_cancel_forwarding(t2.id);exception when others then err:=sqlerrm;end;if err is null then raise exception '待审核凭证可取消';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 r:=public.admin_review_payment_receipt(r.id,true,f.total_amount,'QA-FORWARD-REF','隔离验收',true);
 if exists(select 1 from public.payment_notifications where order_id=t2.id and (message like '%打包%' or title like '%打包%')) then raise exception '整包转寄付款通知仍要求打包';end if;
 perform set_config('request.jwt.claim.sub',m::text,true);
 err:=null;begin perform public.merchant_cancel_forwarding(t2.id);exception when others then err:=sqlerrm;end;if err is null then raise exception '已付款可取消';end if;
 perform set_config('request.jwt.claim.sub',w::text,true);
 t2:=public.warehouse_ship_order(t2.id,'J&T 极兔','QA-JT-2');
 again:=public.warehouse_dispatch_forwarding(t2.id,'J&T 极兔','QA-JT-2');
 if t2.status<>'shipped' or again.id<>t2.id or (select status from public.overseas_packages where id=pkg1)<>'dispatched' then raise exception '出库/幂等错误或提前签收';end if;
 err:=null;begin perform public.warehouse_ship_order(t2.id,'J&T','OTHER');exception when others then err:=sqlerrm;end;if err is null then raise exception '已出库可覆盖单号';end if;
 t2:=public.warehouse_complete_delivery(t2.id,'QA承运商签收记录核实');
 if t2.status<>'delivered' or (select status from public.overseas_packages where id=pkg1)<>'delivered' or (select status from public.overseas_packages where id=pkg2)<>'reserved' or (select status from public.overseas_packages where id=pkg3)<>'available' then raise exception '签收错误更新其他箱';end if;
 if (select total_amount from public.fees where order_id=h.id)<>78 or (select count(*) from public.payments where order_id=t2.id)<>1 then raise exception '改写头程金额或重复付款';end if;
 insert into qa_forwarding_results values('独立核价付款审核、审核中及已付款不可取消、出库不等于签收、幂等出库、不能覆盖单号、签收仅更新本单整包','PASS');
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 if exists(select 1 from public.overseas_packages) or exists(select 1 from public.forwarding_order_packages) then raise exception '其他账号可读库存明细';end if;
 perform set_config('request.jwt.claim.sub',m::text,true);
 err:=null;begin perform public.merchant_create_distance_last_mile(h.id,recipient,z.id,z.updated_at);exception when others then err:=sqlerrm;end;if err is null then raise exception '旧接口可绕过库存';end if;
 insert into qa_forwarding_results values('跨账号库存隔离、旧建单接口不可绕过实际包裹库存','PASS');
end $$;
reset role;
select * from qa_forwarding_results;
rollback;
